import{_ as e,C as a,c as i,o as t,j as r,b as n,a0 as l,a as s,w as o,G as u,a1 as c}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Élaborer sa routine d&#39;avant-tir","description":"","frontmatter":{},"headers":[],"relativePath":"fr/education/mental-strength/pre-shot-routine.md","filePath":"fr/education/mental-strength/pre-shot-routine.md"}');const p=e({name:"fr/education/mental-strength/pre-shot-routine.md"},[["render",function(e,d,p,h,m,f){const v=a("Mermaid");return t(),i("div",null,[d[1]||(d[1]=r("h1",{id:"elaborer-sa-routine-d-39-avant-tir",tabindex:"-1"},[s("Élaborer sa routine d'avant-tir "),r("a",{class:"header-anchor",href:"#elaborer-sa-routine-d-39-avant-tir","aria-label":'Permalink to "Élaborer sa routine d&#39;avant-tir"'},"​")],-1)),d[2]||(d[2]=r("p",null,"Votre routine d'avant-lancer est l'un des outils les plus puissants de votre préparation mentale. Il s'agit d'une séquence d'actions régulières qui vous prépare à chaque lancer et vous permet d'atteindre votre performance optimale.",-1)),d[3]||(d[3]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"La grande idée"),r("p",null,[r("strong",null,"Votre routine est la clé de votre performance optimale."),s(" Une routine d'avant-tir régulière signale à votre cerveau : « C'est le moment de passer à l'action. » Avec la répétition, elle devient un déclencheur automatique pour une performance maximale.")])],-1)),(t(),n(c,null,{default:o(()=>[u(v,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BD%C3%A9but%20de%20la%20routine%5D%20--%3E%20B%5BLe%20cerveau%20reconna%C3%AEt%20un%20sch%C3%A9ma%5D%0A%20%20%20%20B%20--%3E%20C%5BChangement%20d%26%2339%3B%C3%A9tat%20automatique%5D%0A%20%20%20%20C%20--%3E%20D%5BMode%20d%26%2339%3Bex%C3%A9cution%5D%0A%20%20%20%20D%20--%3E%20E%5BPerformance%20optimale%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...d[0]||(d[0]=[s(" Loading... ",-1)])]),_:1})),d[4]||(d[4]=l('<h2 id="pourquoi-les-routines-fonctionnent" tabindex="-1">Pourquoi les routines fonctionnent <a class="header-anchor" href="#pourquoi-les-routines-fonctionnent" aria-label="Permalink to &quot;Pourquoi les routines fonctionnent&quot;">​</a></h2><h3 id="la-constance-engendre-la-confiance" tabindex="-1">La constance engendre la confiance <a class="header-anchor" href="#la-constance-engendre-la-confiance" aria-label="Permalink to &quot;La constance engendre la confiance&quot;">​</a></h3><p>En répétant systématiquement les mêmes gestes, on élimine les variables. Le corps sait à quoi s&#39;attendre. Cela crée un sentiment de contrôle et de familiarité, même dans des situations inédites.</p><h3 id="les-routines-declenchent-des-etats" tabindex="-1">Les routines déclenchent des états <a class="header-anchor" href="#les-routines-declenchent-des-etats" aria-label="Permalink to &quot;Les routines déclenchent des états&quot;">​</a></h3><p>Avec la répétition, votre routine s&#39;intègre à votre état de performance. Le simple fait de commencer la routine amorce automatiquement le passage mental en mode exécution.</p><h3 id="les-routines-bloquent-les-distractions" tabindex="-1">Les routines bloquent les distractions <a class="header-anchor" href="#les-routines-bloquent-les-distractions" aria-label="Permalink to &quot;Les routines bloquent les distractions&quot;">​</a></h3><p>Une routine permet à l&#39;esprit de se concentrer sur quelque chose. Il n&#39;y a plus de place pour s&#39;inquiéter du score, du public ou de ce qui pourrait arriver.</p><h3 id="les-routines-gerent-l-39-excitation" tabindex="-1">Les routines gèrent l&#39;excitation <a class="header-anchor" href="#les-routines-gerent-l-39-excitation" aria-label="Permalink to &quot;Les routines gèrent l&amp;#39;excitation&quot;">​</a></h3><p>Une routine bien conçue aide à réguler votre niveau d&#39;énergie : elle vous calme si vous êtes trop excité, elle vous aide à vous concentrer si vous manquez d&#39;énergie.</p><h2 id="elements-d-39-une-routine-efficace" tabindex="-1">Éléments d&#39;une routine efficace <a class="header-anchor" href="#elements-d-39-une-routine-efficace" aria-label="Permalink to &quot;Éléments d&amp;#39;une routine efficace&quot;">​</a></h2><h3 id="phase-1-evaluation-hors-du-cercle" tabindex="-1">Phase 1 : Évaluation (Hors du cercle) <a class="header-anchor" href="#phase-1-evaluation-hors-du-cercle" aria-label="Permalink to &quot;Phase 1 : Évaluation (Hors du cercle)&quot;">​</a></h3><p>Avant d&#39;intervenir, rassemblez des informations :</p><ul><li>Analysez le terrain (pentes, obstacles, surface).</li><li>Évaluer la situation (score, positions des boules)</li><li>Choisissez votre cible et votre point d&#39;atterrissage</li><li>Choisissez le type de lancer (pointer, tirer, lober, rouler)</li></ul><p><strong>C&#39;est ici que se produit la réflexion.</strong> Prenez votre temps.</p><h3 id="phase-2-transition-entree-dans-le-cercle" tabindex="-1">Phase 2 : Transition (Entrée dans le cercle) <a class="header-anchor" href="#phase-2-transition-entree-dans-le-cercle" aria-label="Permalink to &quot;Phase 2 : Transition (Entrée dans le cercle)&quot;">​</a></h3><p>Le passage de la réflexion à l&#39;action :</p><ul><li>Action physique (entrer dans le cercle de manière régulière)</li><li>Signal mental (un mot ou une phrase qui signale le « mode d&#39;exécution »)</li><li>Respiration (une respiration consciente pour se recentrer)</li></ul><p><strong>C&#39;est le point de bascule.</strong> L&#39;analyse s&#39;arrête ici.</p><h3 id="phase-3-installation-dans-le-cercle" tabindex="-1">Phase 3 : Installation (Dans le cercle) <a class="header-anchor" href="#phase-3-installation-dans-le-cercle" aria-label="Permalink to &quot;Phase 3 : Installation (Dans le cercle)&quot;">​</a></h3><p>Préparez votre corps :</p><ul><li>Position constante (la même à chaque fois)</li><li>Vérification de la prise en main (sentir la boule)</li><li>Alignement sur la cible</li><li>Déclencheur physique (un petit mouvement qui vous est propre)</li></ul><h3 id="phase-4-visualisation-bref" tabindex="-1">Phase 4 : Visualisation (Bref) <a class="header-anchor" href="#phase-4-visualisation-bref" aria-label="Permalink to &quot;Phase 4 : Visualisation (Bref)&quot;">​</a></h3><p>Visualisez le lancer avant de l&#39;effectuer :</p><ul><li>Visualisez la trajectoire de la balle (2 à 3 secondes maximum).</li><li>Ressentez le lancer réussi</li><li>Établissez un lien visuel avec votre cible</li></ul><h3 id="phase-5-execution" tabindex="-1">Phase 5 : Exécution <a class="header-anchor" href="#phase-5-execution" aria-label="Permalink to &quot;Phase 5 : Exécution&quot;">​</a></h3><p>Effectuez le lancer :</p><ul><li>Mise au point externe (cible uniquement)</li><li>Faites confiance à votre corps</li><li>Libérer sans hésitation</li><li>Suivre naturellement</li></ul><h2 id="creer-sa-routine-personnelle" tabindex="-1">Créer sa routine personnelle <a class="header-anchor" href="#creer-sa-routine-personnelle" aria-label="Permalink to &quot;Créer sa routine personnelle&quot;">​</a></h2><h3 id="etape-1-observez-ce-que-vous-faites-deja" tabindex="-1">Étape 1 : Observez ce que vous faites déjà <a class="header-anchor" href="#etape-1-observez-ce-que-vous-faites-deja" aria-label="Permalink to &quot;Étape 1 : Observez ce que vous faites déjà&quot;">​</a></h3><p>Vous avez probablement déjà une routine. Remarque :</p><ul><li>Que fais-tu avant de réussir de bons lancers ?</li><li>Qu&#39;est-ce qui vous semble naturel ?</li><li>Qu&#39;est-ce qui vous aide à vous concentrer ?</li></ul><h3 id="etape-2-concevez-votre-routine" tabindex="-1">Étape 2 : Concevez votre routine <a class="header-anchor" href="#etape-2-concevez-votre-routine" aria-label="Permalink to &quot;Étape 2 : Concevez votre routine&quot;">​</a></h3><p>Créez une séquence qui comprend :</p><ul><li>[ ] Phase d&#39;évaluation</li><li>[ ] Moment de transition clair</li><li>[ ] Configuration physique cohérente</li><li>[ ] brève visualisation</li><li>[ ] Déclencheur d&#39;exécution</li></ul><h3 id="etape-3-notez-le" tabindex="-1">Étape 3 : Notez-le <a class="header-anchor" href="#etape-3-notez-le" aria-label="Permalink to &quot;Étape 3 : Notez-le&quot;">​</a></h3><p>Soyez précis. Exemple :</p><ol><li><strong>Évaluation :</strong> Analyser le terrain, choisir le point d&#39;atterrissage</li><li><strong>Transition :</strong> Entrez dans le cercle en commençant par le pied gauche, dites « confiance ».</li><li><strong>Préparation :</strong> Pieds écartés à la largeur des épaules, vérification de la prise en main, alignement des épaules</li><li><strong>Visualisez :</strong> Voyez le chemin, ressentez la libération</li><li><strong>Exécution :</strong> Gardez la cible en ligne de mire, lancez.</li></ol><h3 id="etape-4-pratiquer-religieusement" tabindex="-1">Étape 4 : Pratiquer religieusement <a class="header-anchor" href="#etape-4-pratiquer-religieusement" aria-label="Permalink to &quot;Étape 4 : Pratiquer religieusement&quot;">​</a></h3><p>Utilisez votre routine à CHAQUE lancer à l&#39;entraînement :</p><ul><li>lancers faciles</li><li>lancers difficiles</li><li>Quand on est fatigué</li><li>Quand tu es frais</li></ul><p>La routine doit devenir automatique.</p><h3 id="etape-5-ameliorer-au-fil-du-temps" tabindex="-1">Étape 5 : Améliorer au fil du temps <a class="header-anchor" href="#etape-5-ameliorer-au-fil-du-temps" aria-label="Permalink to &quot;Étape 5 : Améliorer au fil du temps&quot;">​</a></h3><p>Votre routine évoluera. Observez ce qui fonctionne et adaptez-la. Mais ne la modifiez pas pendant la compétition ; seulement entre les épreuves.</p><h2 id="horaire-de-routine" tabindex="-1">Horaire de routine <a class="header-anchor" href="#horaire-de-routine" aria-label="Permalink to &quot;Horaire de routine&quot;">​</a></h2><p>Votre routine doit prendre un temps constant :</p><ul><li>Trop rapide : vous vous précipitez, vous n&#39;êtes pas suffisamment préparé.</li><li>Trop lent : vous réfléchissez trop, vous perdez le fil.</li><li>Juste ce qu&#39;il faut : assez de temps pour se préparer, pas trop pour ne pas trop réfléchir.</li></ul><p><strong>Délai habituel :</strong></p><ul><li>Évaluation : 5 à 10 secondes</li><li>Transition + Préparation : 3 à 5 secondes</li><li>Visualisation + Exécution : 3 à 5 secondes</li><li><strong>Durée totale : 10 à 20 secondes</strong></li></ul><h2 id="erreurs-de-routine-courantes" tabindex="-1">Erreurs de routine courantes <a class="header-anchor" href="#erreurs-de-routine-courantes" aria-label="Permalink to &quot;Erreurs de routine courantes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Erreur</th><th>Problème</th><th>Solution</th></tr></thead><tbody><tr><td>Sauter à la corde à sauter en entraînement</td><td>La routine n&#39;est pas automatique</td><td>Utilisez-le à chaque lancer</td></tr><tr><td>Trop compliqué</td><td>Difficile à retenir sous pression</td><td>Simplifier à l&#39;essentiel</td></tr><tr><td>Réflexion pendant l&#39;exécution</td><td>Perturbe les performances automatiques</td><td>Point de transition clair</td></tr><tr><td>Temporisation incohérente</td><td>Crée de l&#39;incertitude</td><td>Pratiquez à un rythme constant</td></tr><tr><td>Changement en cours de compétition</td><td>Introduit le doute</td><td>Restez fidèle à ce que vous connaissez.</td></tr></tbody></table><h2 id="depannage-de-routine" tabindex="-1">Dépannage de routine <a class="header-anchor" href="#depannage-de-routine" aria-label="Permalink to &quot;Dépannage de routine&quot;">​</a></h2><p><strong>Si vous êtes pressé :</strong></p><ul><li>Ajoutez une respiration à la transition</li><li>Ralentissez vos mouvements de préparation</li><li>Pause avant la visualisation</li></ul><p><strong>Si vous réfléchissez trop :</strong></p><ul><li>Raccourcir la routine</li><li>Utilisez un signal de transition plus marqué.</li><li>Concentrez-vous davantage sur l&#39;extérieur</li></ul><p><strong>Si vous êtes incohérent :</strong></p><ul><li>Filmez-vous vous-même pour vérifier</li><li>Répétez la routine sans lancer</li><li>Obtenez un retour d&#39;information de votre partenaire</li></ul><h2 id="exemples-de-routines" tabindex="-1">Exemples de routines <a class="header-anchor" href="#exemples-de-routines" aria-label="Permalink to &quot;Exemples de routines&quot;">​</a></h2><h3 id="routine-simple" tabindex="-1">Routine simple <a class="header-anchor" href="#routine-simple" aria-label="Permalink to &quot;Routine simple&quot;">​</a></h3><ol><li>Choisir la cible</li><li>Entrez, respirez</li><li>Saisir, aligner</li><li>Tu le vois, tu le jettes</li></ol><h3 id="routine-detaillee" tabindex="-1">Routine détaillée <a class="header-anchor" href="#routine-detaillee" aria-label="Permalink to &quot;Routine détaillée&quot;">​</a></h3><ol><li>Analysez le terrain, choisissez votre point d&#39;atterrissage</li><li>Avancez d&#39;abord le pied gauche.</li><li>Prononcez « lisse » intérieurement</li><li>Une respiration, les épaules s&#39;affaissent</li><li>Pieds positionnés, vérification de l&#39;adhérence</li><li>Alignez les épaules sur la cible</li><li>Voir le chemin (2 secondes)</li><li>Les yeux se fixent sur la cible</li><li>Lancer</li></ol><h2 id="points-cles-a-retenir" tabindex="-1">Points clés à retenir <a class="header-anchor" href="#points-cles-a-retenir" aria-label="Permalink to &quot;Points clés à retenir&quot;">​</a></h2><blockquote><p>Votre routine est votre point d&#39;ancrage. Dans le chaos, c&#39;est votre constante.</p></blockquote><p>Construisez-le avec soin. Entraînez-vous sans cesse. Ayez une confiance absolue en lui.</p>',65))])}]]);export{d as __pageData,p as default};
